cypress_script:
describe('Shopping Cart Page Tests', () => {
  it('should display the shopping cart with items', () => {
    cy.visit('https://www.saucedemo.com/cart.html');
    cy.get('[data-test="title"]').should('be.visible');
    cy.get('[data-test="continue-shopping"]').should('be.visible');
    cy.get('[data-test="checkout"]').should('be.visible');
  });
  it('should not navigate away from the cart page when clicking continue shopping', () => {
    cy.visit('https://www.saucedemo.com/cart.html');
    cy.get('[data-test="continue-shopping"]').click();
    cy.url().should('eq', 'https://www.saucedemo.com/cart.html');
    cy.get('[data-test="title"]').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Shopping Cart Page Tests', () => {
  test('should display the shopping cart with items', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/cart.html');
    await expect(page.locator('[data-test="title"]')).toBeVisible();
    await expect(page.locator('[data-test="continue-shopping"]')).toBeVisible();
    await expect(page.locator('[data-test="checkout"]')).toBeVisible();
  });
  test('should not navigate away from the cart page when clicking continue shopping', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/cart.html');
    await page.click('[data-test="continue-shopping"]');
    await expect(page).toHaveURL('https://www.saucedemo.com/cart.html');
    await expect(page.locator('[data-test="title"]')).toBeVisible();
  });
});
